/**
 * Seed script for QuickSkill v2.
 *
 * Populates Firestore with expanded skills, topic-tagged questions,
 * learning explanations, and varied interaction types.
 *
 * Usage:
 *   1. Set FIREBASE_SERVICE_ACCOUNT_PATH in .env
 *   2. Run: npm run seed
 */

import { readFileSync, existsSync } from 'fs';
import { createRequire } from 'module';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));

function loadEnv() {
  const envPath = resolve(__dirname, '..', '.env');
  if (!existsSync(envPath)) return;
  const content = readFileSync(envPath, 'utf-8');
  for (const line of content.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;
    const key = trimmed.slice(0, eqIdx).trim();
    const value = trimmed.slice(eqIdx + 1).trim();
    if (!process.env[key]) process.env[key] = value;
  }
}

loadEnv();

const require = createRequire(import.meta.url);
const admin = require('firebase-admin');

const serviceAccountPath =
  process.env.FIREBASE_SERVICE_ACCOUNT_PATH ||
  process.env.GOOGLE_APPLICATION_CREDENTIALS;

if (!serviceAccountPath) {
  console.error('Error: FIREBASE_SERVICE_ACCOUNT_PATH must be set.');
  process.exit(1);
}

const resolvedPath = resolve(__dirname, '..', serviceAccountPath);
let serviceAccount;
try {
  serviceAccount = JSON.parse(readFileSync(resolvedPath, 'utf-8'));
} catch {
  try { serviceAccount = require(resolvedPath); } catch {
    console.error('Error: Could not load service account from:', resolvedPath);
    process.exit(1);
  }
}

admin.initializeApp({ credential: admin.credential.cert(serviceAccount) });
const db = admin.firestore();

